import{_ as a,o as e,c as i,a4 as d}from"./chunks/framework.BybBnFXO.js";const _=JSON.parse('{"title":"物理性质测试","description":"","frontmatter":{"title":"物理性质测试","identification":"physical-tests"},"headers":[],"relativePath":"zh/identification/physical-tests.md","filePath":"zh/identification/physical-tests.md","lastUpdated":1785885709000}'),r={name:"zh/identification/physical-tests.md"};function l(o,t,s,h,n,c){return e(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="物理性质测试" tabindex="-1">物理性质测试 <a class="header-anchor" href="#物理性质测试" aria-label="Permalink to &quot;物理性质测试&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>折射率 (RI)、比重 (SG)、硬度、解理是最基础的鉴定手段——它们由 矿物化学成分与晶体结构决定，同一矿物种的值恒定可重复。</p><h2 id="核心要点" tabindex="-1">核心要点 <a class="header-anchor" href="#核心要点" aria-label="Permalink to &quot;核心要点&quot;">​</a></h2><ul><li>折射率 (RI)：折射仪读数，钻石 2.42、刚玉 1.76、石英 1.54 等。</li><li>比重 (SG)：空气中与水中称重比，可区分同色不同种宝石。</li><li>硬度：莫氏 1–10，划痕测试是破坏性的，只在必要时用。</li><li>解理：沿原子面断裂的倾向，钻石八面体解理、宝石级可见。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宝石</th><th>数值</th><th>备注</th></tr></thead><tbody><tr><td>diamond</td><td>RI 2.42, SG 3.52</td><td>—</td></tr><tr><td>ruby</td><td>RI 1.76, SG 4.00</td><td>—</td></tr></tbody></table><p><em>详见<a href="./intro.html">鉴定总览</a>。</em></p>',8)])])}const f=a(r,[["render",l]]);export{_ as __pageData,f as default};
